"use client";

import { useId, useState } from "react";

import { DownloadIcon } from "@/components/blocks/parts/icons";
import { NumberTicker } from "@/components/motion/number-ticker";
import { SegmentedControl } from "@/components/motion/segmented-control";
import { Switch } from "@/components/motion/switch";
import { Button } from "@/components/ui/button";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { cn } from "@/lib/utils";

import { formatDay, formatOnePlace, formatWeekday, formatWhole, sampleDate } from "../lib/format";
import { makeSeries, mean, percentChange, sum } from "../lib/plot";
import { usePointCursor } from "../lib/use-point-cursor";
import { BarList, type BarListItem } from "../parts/bar-list";
import { BlockFrame } from "../parts/block-frame";
import { Delta } from "../parts/delta";
import { Sparkline } from "../parts/sparkline";
import { TrendChart } from "../parts/trend-chart";

type Range = "7" | "30" | "90";
type MetricId = "bookings" | "patients" | "noShows" | "wait";

interface Metric {
  id: MetricId;
  label: string;
  /** The noun used in a sentence, such as "bookings". */
  noun: string;
  /** The last 180 days: the newest 90 are the period, the 90 before are the comparison. */
  days: number[];
  /** A total adds the days up. An average takes their mean. */
  kind: "total" | "average";
  lowerIsBetter: boolean;
  format: (value: number) => string;
  /** How the rolling headline figure is written, and the unit after it. */
  roll: Intl.NumberFormatOptions;
  unit?: string;
}

const RANGES: { value: Range; label: string }[] = [
  { value: "7", label: "7 days" },
  { value: "30", label: "30 days" },
  { value: "90", label: "90 days" },
];

const WHOLE: Intl.NumberFormatOptions = { maximumFractionDigits: 0 };
const ONE_PLACE: Intl.NumberFormatOptions = { minimumFractionDigits: 1, maximumFractionDigits: 1 };

const minutes = (value: number) => `${formatOnePlace(value)} min`;

const METRICS: Metric[] = [
  { id: "bookings", label: "Bookings", noun: "bookings", days: makeSeries(11, 180, 118, 196, 34), kind: "total", lowerIsBetter: false, format: formatWhole, roll: WHOLE },
  { id: "patients", label: "New patients", noun: "new patients", days: makeSeries(23, 180, 21, 38, 9), kind: "total", lowerIsBetter: false, format: formatWhole, roll: WHOLE },
  { id: "noShows", label: "No-shows", noun: "no-shows", days: makeSeries(37, 180, 14, 9, 5), kind: "total", lowerIsBetter: true, format: formatWhole, roll: WHOLE },
  { id: "wait", label: "Average wait", noun: "minutes of waiting", days: makeSeries(53, 180, 11.5, 8.2, 2.4), kind: "average", lowerIsBetter: true, format: minutes, roll: ONE_PLACE, unit: "min" },
];

// Each list splits the bookings total, so its rows always add up to the headline figure.
const CLINIC_SHARES: [string, number][] = [
  ["Harbour Street", 0.3],
  ["Mill Lane", 0.25],
  ["Northgate", 0.2],
  ["Orchard Road", 0.15],
  ["The Quay", 0.1],
];

const CHANNEL_SHARES: [string, number][] = [
  ["Booking page", 0.52],
  ["Phone", 0.24],
  ["Front desk", 0.13],
  ["Reminder link", 0.07],
  ["Sent by a doctor", 0.04],
];

/** Splits a whole-number total by shares. The largest row takes the rounding remainder. */
function splitTotal(total: number, shares: [string, number][]): BarListItem[] {
  const whole = Math.round(total);
  const rows = shares.map(([label, share]) => ({ label, value: Math.round(whole * share) }));
  const first = rows[0];
  if (first) first.value += whole - rows.reduce((sum, row) => sum + row.value, 0);
  return rows;
}

/** The figures of one metric over one range: the period, the period before it, and both headline numbers. */
function readMetric(metric: Metric, range: Range) {
  const length = Number(range);
  const current = metric.days.slice(-length);
  const previous = metric.days.slice(-length * 2, -length);
  const headline = metric.kind === "total" ? sum : mean;
  const now = headline(current);
  const before = headline(previous);
  return { current, previous, now, before, change: percentChange(before, now) };
}

/**
 * A dense analytics view: pick a range and one of four figures, read its
 * trend against the period before, then see where it came from. The summary
 * sentence states the result in words, so the chart is never the only source.
 */
export function MetricsDashboard({ className }: { className?: string }) {
  const [range, setRange] = useState<Range>("30");
  const [metricId, setMetricId] = useState<MetricId>("bookings");
  const [compare, setCompare] = useState(true);
  const titleId = useId();
  const compareId = useId();

  const metric = METRICS.find((item) => item.id === metricId) ?? METRICS[0]!;
  const figures = readMetric(metric, range);
  const cursor = usePointCursor(figures.current.length);
  const length = figures.current.length;

  const bookings = readMetric(METRICS[0]!, range).now;

  const busiest = figures.current.indexOf(Math.max(...figures.current));
  // One short line that fits the chart's fixed-height slot at every width, so nothing under it moves.
  const summary = `${metric.label} peaked on ${formatWeekday(sampleDate(length - 1 - busiest))}, ${formatDay(sampleDate(length - 1 - busiest))}.`;

  const describePoint = (index: number) => {
    const value = figures.current[index] ?? 0;
    const earlier = figures.previous[index] ?? 0;
    const base = `${formatDay(sampleDate(length - 1 - index))}: ${metric.format(value)}`;
    return compare ? `${base}, against ${metric.format(earlier)} on the same day of the period before.` : `${base}.`;
  };

  const pointDetails = (index: number) => {
    const value = figures.current[index] ?? 0;
    const earlier = figures.previous[index] ?? 0;
    const day = sampleDate(length - 1 - index);
    const change = percentChange(earlier, value);
    return {
      title: `${formatWeekday(day)}, ${formatDay(day)}`,
      rows: compare
        ? [
            { label: metric.label, value: metric.format(value), marker: "bg-chart-1" },
            { label: `${range} days before`, value: metric.format(earlier), marker: "bg-muted-foreground", dashed: true },
          ]
        : [{ label: metric.label, value: metric.format(value), marker: "bg-chart-1" }],
      note: compare ? `${change >= 0 ? "Up" : "Down"} ${formatOnePlace(Math.abs(change))}% on that day` : undefined,
    };
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-center justify-between gap-x-6 gap-y-3 border-b border-border px-5 py-4">
        <div className="min-w-0">
          <h2 id={titleId} className="text-base font-semibold">
            Fernhill clinics
          </h2>
          <p className="text-sm text-muted-foreground">
            {formatDay(sampleDate(length - 1))} to {formatDay(sampleDate(0))}
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <SegmentedControl aria-label="Date range" options={RANGES} value={range} onValueChange={setRange} />
          <Button variant="outline" size="sm">
            <DownloadIcon aria-hidden="true" className="size-4" />
            Download data
          </Button>
        </div>
      </header>

      <div className="grid @3xl:grid-cols-[17rem_1fr]">
        {/* The line colour shows through the one-pixel gaps between the tiles. */}
        <div className="grid grid-cols-2 gap-px border-b border-border bg-border @3xl:grid-cols-1 @3xl:border-r @3xl:border-b-0">
        <RadioGroup
          aria-label="Figure to chart"
          value={metricId}
          onValueChange={(id) => {
            const next = METRICS.find((item) => item.id === id);
            if (next) setMetricId(next.id);
          }}
          className="contents"
        >
          {METRICS.map((item) => {
            const reading = readMetric(item, range);
            const checked = item.id === metricId;
            return (
              <label
                key={item.id}
                className={cn(
                  "group relative isolate flex cursor-pointer items-end justify-between gap-3 bg-card px-5 py-4 outline-none",
                  "has-focus-visible:z-10 has-focus-visible:ring-2 has-focus-visible:ring-ring has-focus-visible:ring-inset",
                )}
              >
                {/* The tint sits over the card colour. A see-through fill on the tile itself would show the grid's line colour through it. */}
                <span
                  aria-hidden="true"
                  className={cn("absolute inset-0 -z-10", checked ? "bg-muted/60" : "group-hover:bg-muted/30")}
                />
                <RadioGroupItem value={item.id} className="sr-only" />
                {checked ? <span aria-hidden="true" className="absolute inset-y-3 left-0 w-0.5 rounded-full bg-chart-1" /> : null}
                <span className="flex min-w-0 flex-col gap-1">
                  <span className="text-sm text-muted-foreground">{item.label}</span>
                  <span className="flex items-baseline gap-1 text-2xl font-semibold tracking-tight">
                    <NumberTicker value={item.kind === "total" ? Math.round(reading.now) : reading.now} format={item.roll} />
                    {item.unit ? <span>{item.unit}</span> : null}
                  </span>
                  <Delta value={reading.change} lowerIsBetter={item.lowerIsBetter} />
                </span>
                <Sparkline values={reading.current} className={cn("hidden @md:block", checked ? "text-chart-1" : undefined)} />
              </label>
            );
          })}
        </RadioGroup>
        </div>

        <div className="flex min-w-0 flex-col gap-4 p-5">
          <div className="flex flex-wrap items-center justify-between gap-3">
            <h3 className="text-sm font-medium">{metric.label} by day</h3>
            <label htmlFor={compareId} className="flex cursor-pointer items-center gap-2 text-sm text-muted-foreground">
              Compare with the {range} days before
              <Switch id={compareId} checked={compare} onCheckedChange={setCompare} />
            </label>
          </div>
          <TrendChart
            label={`${metric.label}, last ${range} days`}
            values={figures.current}
            compare={compare ? figures.previous : null}
            axisLabels={[formatDay(sampleDate(length - 1)), formatDay(sampleDate(Math.floor((length - 1) / 2))), formatDay(sampleDate(0))]}
            formatAxis={metric.kind === "average" ? formatOnePlace : formatWhole}
            describePoint={describePoint}
            pointDetails={pointDetails}
            summary={summary}
            cursor={cursor}
          />
        </div>
      </div>

      <div className="grid gap-x-8 gap-y-6 border-t border-border p-5 @2xl:grid-cols-2">
        <BarList title="Busiest clinics" unit="Bookings" items={splitTotal(bookings, CLINIC_SHARES)} format={formatWhole} />
        <BarList title="How patients booked" unit="Bookings" items={splitTotal(bookings, CHANNEL_SHARES)} format={formatWhole} />
      </div>
    </BlockFrame>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

