/** Props for a change figure. */
export interface DeltaProps {
  /** The percent change. */
  value: number;
  /** Set when a fall is the good direction, such as no-shows or waiting time. */
  lowerIsBetter?: boolean;
  className?: string;
}

/**
 * A percent change with an arrow. The arrow and the spoken word carry the
 * direction, and the colour says only whether the change is good.
 */
export function Delta({ value, lowerIsBetter = false, className }: DeltaProps) {
  const flat = Math.abs(value) < 0.05;
  const up = value > 0;
  const good = flat ? null : up !== lowerIsBetter;
  const Arrow = up ? ArrowUpIcon : ArrowDownIcon;
  return (
    <span
      className={cn(
        "inline-flex items-center gap-0.5 text-xs font-medium tabular-nums",
        good === null ? "text-muted-foreground" : STATUS_TEXT[good ? "good" : "bad"],
        className,
      )}
    >
      {flat ? null : <Arrow aria-hidden="true" className="size-3" />}
      <span className="sr-only">{flat ? "No change" : up ? "Up" : "Down"}</span>
      {formatPercent(value)}
    </span>
  );
}

/** The three states a figure or a row can be in. */
export type Status = "good" | "watch" | "bad";

/** The text colour for each state. Each one passes 4.5 to 1 on a card in both themes. */
export const STATUS_TEXT = {
  good: "text-marketing-green-ink",
  watch: "text-marketing-amber-ink",
  bad: "text-marketing-orange-ink",
} satisfies Record<Status, string>;

/** A tinted surface for each state, for a pill or a cell. Pair it with the matching text colour. */
export const STATUS_SURFACE = {
  good: "bg-marketing-green-surface",
  watch: "bg-marketing-amber-surface",
  bad: "bg-marketing-orange-surface",
} satisfies Record<Status, string>;

/** The word a screen reader and a label use for each state. Colour never carries a state alone. */
export const STATUS_WORD = {
  good: "Good",
  watch: "Watch",
  bad: "At risk",
} satisfies Record<Status, string>;

